	"dataSources": {
		"ds_11iP0arU": {
			"name": "Column - Analyze costs by service name",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumBilledCost) AS TotalBilledCost, sum(sumEffectiveCost) AS TotalEffectiveCost BY ServiceName \n| sort -TotalBilledCost\n| head 10"
			},
			"type": "ds.chain"
		},
		"ds_B3RhMu3h": {
			"name": "Table - Tagged Services",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" SubAccountName IN ($SubAccountNameMulti|s$) EffectiveCost > 0 \n| eval has_tags = case(match(Tags, \"'$tag$':\\\\s*'[^']+'\"), 1,match(Tags, \"\\\"$tag$\\\":\\\\s*\\\"[^\\\"]+\\\"\"), 1,true(),0)\n| stats count as total count(eval(has_tags=1)) as tagged by ProviderName ServiceCategory ServiceName SubAccountName RegionName \n| eval TaggedPercentage = round((tagged/total)*100, 2) \n| table ProviderName ServiceCategory ServiceName SubAccountName RegionName TaggedPercentage \n| sort TaggedPercentage"
			},
			"type": "ds.chain"
		},
		"ds_BKPqLVYx": {
			"name": "BASE Search with Filter",
			"options": {
				"query": "| `focus_search`\nAND cost.ProviderName IN ($ProviderName|s$) \nAND cost.SubAccountName IN ($SubAccountName|s$) \nAND cost.ServiceCategory IN ($ServiceCategory|s$)\nAND cost.ServiceName IN ($ServiceName|s$) \n`focus_tstats_by`",
				"queryParameters": {}
			},
			"type": "ds.search"
		},
		"ds_FtFtD7k0": {
			"name": "Column - SingleValue - Tagged by Service Category",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" SubAccountName IN ($SubAccountNameMulti|s$) EffectiveCost > 0\n| eval tagged = case(match(Tags, \"'$tag$':\\\\s*'[^']+'\"), 1,match(Tags, \"\\\"$tag$\\\":\\\\s*\\\"[^\\\"]+\\\"\"), 1,true(),0)\n| stats count as total count(eval(tagged=1)) as tagged by ProviderName ServiceCategory ServiceName SubAccountName RegionName \n| eval TaggedPercentage = round((tagged/total)*100, 2) \n| table ProviderName ServiceCategory ServiceName SubAccountName RegionName TaggedPercentage \n| stats avg(TaggedPercentage) as TaggedPercentage by ServiceCategory \n| eval TaggedPercentage = round(TaggedPercentage,2)"
			},
			"type": "ds.chain"
		},
		"ds_GRYb62GI": {
			"name": "Dropdown - Resource Name",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| dedup ResourceName\n| table ResourceName"
			},
			"type": "ds.chain"
		},
		"ds_IUcKepfO": {
			"name": "Multiselect - Sub Account Name",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| stats sum(BilledCost) AS TotalBilledCost \n    BY SubAccountName \n| sort -TotalBilledCost SubAccountName \n| table SubAccountName"
			},
			"type": "ds.chain"
		},
		"ds_KZW0ZR0W": {
			"name": "SingleValue - Tag Coverage",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "`focus_tag`\n`focus_tag_timetable`\n| eval tag_perc = case(isnull(tag_perc), 0, 1=1, tag_perc)\n| stats latest(tag_perc) as tag_perc by _time\n| where tag_perc like(\"%\")"
			},
			"type": "ds.chain"
		},
		"ds_Po23iE7j": {
			"name": "Table - Analyze cost by region",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY ProviderName, RegionId, RegionName \n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_QK0ChvMa": {
			"name": "Dropdown - Service Name",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\"\n| dedup ServiceName \n| table ServiceName"
			},
			"type": "ds.chain"
		},
		"ds_XbyzyJXx": {
			"name": "Donat - Analyze cost by region",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY RegionId \n| sort ChargePeriodStart, -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_XeZ6WV3f": {
			"name": "Column - Analyze cost by region",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY RegionName \n| eval TotalEffectiveCost = round(TotalEffectiveCost, 2)"
			},
			"type": "ds.chain"
		},
		"ds_Z4i41zgH": {
			"name": "Dropdown - Provider Name",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| dedup ProviderName \n| table ProviderName"
			},
			"type": "ds.chain"
		},
		"ds_a7WsbCId": {
			"name": "Dropdown - Tag",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "`focus_tag_keys`"
			},
			"type": "ds.chain"
		},
		"ds_a7pEdlUM": {
			"name": "Table - Analyze costs by service name",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats sum(sumBilledCost) AS TotalBilledCost,\n    sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY BillingPeriodStart, ProviderName, SubAccountName, ServiceName \n| sort -TotalBilledCost"
			},
			"type": "ds.chain"
		},
		"ds_adHZ9xMP": {
			"name": "Multiselect - Tagged with",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "`focus_tag_values`"
			},
			"type": "ds.chain"
		},
		"ds_eO7Ncs0L": {
			"name": "Table - Analyze costs of components of a resource",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" ResourceName=\"$ResourceName$\" \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY ResourceId, ResourceName, ResourceType, ChargeDescription, SkuId\n| sort -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_h2I5BKS3": {
			"name": "Table - Analyze capacity reservations on compute costs",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ServiceCategory = \"$ServiceCategory$\"\n| eval Status = case(\n    isnotnull(CapacityReservationId) AND CapacityReservationStatus == \"Unused\", \"Unused Capacity Reservation\",\n    isnotnull(CapacityReservationId) AND CapacityReservationStatus == \"Used\", \"Compute using Capacity Reservation\",\n    true(), \"Compute without Capacity Reservation\"\n)\n| stats sum(sumBilledCost) AS TotalBilledCost,\n        sum(sumEffectiveCost) AS TotalEffectiveCost \n    BY Status, ProviderName, BillingAccountId"
			},
			"type": "ds.chain"
		},
		"ds_haBlhCkr": {
			"name": "SingleValue - Total Regions",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" \n| stats dc(RegionName)"
			},
			"type": "ds.chain"
		},
		"ds_kOFJ2BZO": {
			"name": "Table - Analyze service costs month over month",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| eval Month = ChargePeriodStart \n| stats sum(sumEffectiveCost) AS TotalEffectiveCost BY Month, ProviderName, ServiceName \n| sort Month, -TotalEffectiveCost"
			},
			"type": "ds.chain"
		},
		"ds_uGMPkQid": {
			"name": "Column - Analyze costs of components of a resource",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\" ResourceName=\"$ResourceName$\"\n| chart sum(sumEffectiveCost) AS TotalEffectiveCost BY ResourceName, ResourceType"
			},
			"type": "ds.chain"
		},
		"ds_uIIL9hEj": {
			"name": "Column - Analyze service costs month over month",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\" ServiceName=\"$ServiceName$\"\n| timechart span=1mon eval(round(sum(sumEffectiveCost),2)) as TotalEffectiveCost by ServiceName\n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_xSck5l9a": {
			"name": "Dropdown - Service Category",
			"options": {
				"extend": "ds_BKPqLVYx",
				"query": "| search ProviderName=\"$ProviderName$\" \n| dedup ServiceCategory \n| table ServiceCategory"
			},
			"type": "ds.chain"
		}
	},
